package Tiberiu.smartGrid.hybrid;

import java.io.FileReader;
import java.io.IOException;
import java.lang.reflect.Type;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;

import net.xqhs.flash.core.recorder.SimulationEvent;

/**
 * Loads and indexes historical simulation traces generated by {@code FileRecorder}
 * on a per-tick basis, enabling O(1) message lookup during hybrid replay, divergence
 * detection, catch-up state reconstruction, and realignment verification.
 */
public class TickTraceStore {

    /**
     * Immutable representation of a single recorded message exchange at a specific tick.
     */
    public static class RecordedMessage {
        public final long	tick;
        public final String	source;
        public final String	destination;
        public final String	content;

        public RecordedMessage(long tick, String source, String destination, String content) {
            this.tick = tick;
            this.source = source;
            this.destination = destination;
            this.content = content;
        }
    }

    /** Maps simulation tick -> list of outgoing messages recorded at that tick. */
    private final Map<Long, List<RecordedMessage>> messagesByTick = new HashMap<>();

    /**
     * Parses a JSON log file produced by {@code FileRecorder} and indexes outgoing wave events.
     *
     * @param filePath
     *            path to the recorded JSON trace file.
     * @throws IOException
     *             if the file cannot be read.
     */
    public void loadFromJson(String filePath) throws IOException {
        messagesByTick.clear();
        Gson gson = new Gson();
        Type listType = new TypeToken<List<SimulationEvent>>() {
        }.getType();

        try (FileReader reader = new FileReader(filePath)) {
            List<SimulationEvent> events = gson.fromJson(reader, listType);
            if (events == null)
                return;

            for (SimulationEvent ev : events) {
                if ("WAVE_SENT".equals(ev.getType()) || "MESSAGE_STRING".equals(ev.getType())) {
                    long tick = ev.getTick();
                    String source = normalizeAgentName(ev.getEntityName());
                    String dest = normalizeAgentName(extractDestination(ev.getPayload()));
                    String content = extractContent(ev.getPayload());

                    if (source != null && dest != null && content != null) {
                        messagesByTick.computeIfAbsent(tick, k -> new ArrayList<>())
                                .add(new RecordedMessage(tick, source, dest, content));
                    }
                }
            }
        }
    }

    /**
     * Returns all messages recorded at the specified tick.
     *
     * @param tick
     *            the logical simulation tick.
     * @return list of recorded messages at {@code tick}, or an empty list if none exist.
     */
    public List<RecordedMessage> getMessagesAtTick(long tick) {
        return messagesByTick.getOrDefault(tick, Collections.emptyList());
    }

    /**
     * Retrieves all historical messages addressed to a specific agent at a given tick.
     * Used by the catch-up sub-executor to bring promoted agents up to speed.
     *
     * @param agentName
     *            name of the recipient agent.
     * @param tick
     *            the logical simulation tick.
     * @return list of incoming recorded messages for {@code agentName} at {@code tick}.
     */
    public List<RecordedMessage> getIncomingMessagesForAgent(String agentName, long tick) {
        List<RecordedMessage> result = new ArrayList<>();
        for (RecordedMessage msg : getMessagesAtTick(tick)) {
            if (agentName.equals(msg.destination)) {
                result.add(msg);
            }
        }
        return result;
    }

    /**
     * Retrieves all historical messages sent by a specific agent at a given tick.
     * Used by {@link BehavioralRealignmentDetector} to compare current LIVE outputs
     * against baseline behavior for bubble contraction.
     *
     * @param agentName
     *            name of the sender agent.
     * @param tick
     *            the logical simulation tick.
     * @return list of outgoing recorded messages sent by {@code agentName} at {@code tick}.
     */
    public List<RecordedMessage> getOutgoingMessagesForAgent(String agentName, long tick) {
        List<RecordedMessage> result = new ArrayList<>();
        for (RecordedMessage msg : getMessagesAtTick(tick)) {
            if (agentName.equals(msg.source)) {
                result.add(msg);
            }
        }
        return result;
    }

    /**
     * Finds a recorded message matching the given tick, source, and destination.
     * Used to verify whether an outgoing message from a LIVE agent to a MOCKED agent
     * matches the baseline execution.
     *
     * @param tick
     *            the logical simulation tick.
     * @param source
     *            name of the sending agent.
     * @param destination
     *            name of the target agent.
     * @return an {@link Optional} containing the matching recorded message, if present.
     */
    public Optional<RecordedMessage> findMessage(long tick, String source, String destination) {
        for (RecordedMessage msg : getMessagesAtTick(tick)) {
            if (source.equals(msg.source) && destination.equals(msg.destination)) {
                return Optional.of(msg);
            }
        }
        return Optional.empty();
    }

    private String normalizeAgentName(String raw) {
        if (raw == null)
            return null;
        String[] parts = raw.trim().split("/");
        for (String part : parts) {
            if (part.startsWith("Prosumer_") || part.startsWith("Aggregator_")) {
                return part;
            }
        }
        return parts[parts.length - 1];
    }

    @SuppressWarnings("unchecked")
    private String extractDestination(Object payload) {
        if (payload instanceof Map) {
            Map<String, Object> map = (Map<String, Object>) payload;
            Object dest = map.getOrDefault("currentDest", map.get("destination"));
            return dest != null ? dest.toString() : null;
        }
        return null;
    }

    @SuppressWarnings("unchecked")
    private String extractContent(Object payload) {
        if (payload instanceof Map) {
            Map<String, Object> map = (Map<String, Object>) payload;
            Object content = map.get("content");
            return content != null ? content.toString() : null;
        }
        return null;
    }
}